  "nproc"?: number;
  /** Extra route keywords appended verbatim. Gaussian: 'scrf=(solvent=water)', 'empiricaldispersion=gd3bj'; ORCA: 'D3BJ', 'CPCM(water)' (goes onto the `!` line). (default=null) */
  "extra_keywords"?: string | null;
